@php($agentReleaseCatalog = app(\App\Agent\Releases::class)->all())
<section class="card table-card"><div class="table table-responsive"><table><thead><tr><th>Agent</th><th>Versão / status</th><th>Heartbeat</th><th>Poll</th><th>Capabilities</th><th>Última atividade</th></tr></thead><tbody>@forelse($agents as $a)<tr><td data-label="Agent"><div><a href="{{route('agents.show',$a)}}">{{$a->name}}</a><small>{{$a->hostname}}</small>@php($rowUpdates = \App\Agent\ReleaseAvailability::newer($agentReleaseCatalog, $a->version, $a->metadata['lifecycle_components'] ?? [], (int)($a->metadata['lifecycle_release_sequence'] ?? 0)))@if($rowUpdates)<a class="button button-secondary" href="{{route('agents.show',$a)}}#agent-update">Atualizar Agent</a>@elseif($rowUpdates !== null)<small>Não há atualização disponível.</small>@else<small>Versão indisponível para comparação.</small>@endif</div></td><td data-label="Versão / status"><div><x-badge :value="\App\Web\Presentation::agentStatus($a)"/><small>v{{$a->version}}</small></div></td><td data-label="Heartbeat" class="mono">{{\App\Web\Presentation::age($a->last_heartbeat_at)}}</td><td data-label="Poll" class="mono">{{\App\Web\Presentation::age($a->last_poll_at)}}</td><td data-label="Capabilities"><div><strong>{{count($a->capabilities??[])}} disponíveis</strong><details data-detail-key="caps-{{$a->id}}"><summary>Ver capabilities</summary><div class="chip-list">@foreach($a->capabilities??[] as $cap)<span class="chip">{{$cap}}</span>@endforeach</div></details></div></td><td data-label="Última atividade"><div>@php($last=collect([$a->last_poll_at,$a->last_heartbeat_at])->filter()->sortDesc()->first())@if($last)<time datetime="{{$last->toIso8601String()}}">{{\App\Web\Presentation::time($last,'d/m H:i:s T')}}</time>@else Sem atividade @endif</div>@can('delete',$a)<form method="post" action="{{route('agents.destroy',$a)}}" data-confirm="Apagar este Agent revogado da lista? O histórico será preservado.">@csrf @method('DELETE')<button class="button-danger">Apagar</button></form>@endcan</td></tr>@empty<tr><td colspan="